-- Add every Maryland and District of Columbia ZIP to the active service
-- area used by public booking (service_coverage_zones) and internal booking
-- (pricing_zone_zips + coverage fallback).
--
-- Source: GeoNames US postal codes (USPS-derived). IRS 569xx unique ZIPs are
-- excluded. Existing rows stay active; city/tier/multiplier are not overwritten.
-- New ZIPs are mapped to pricing zones A/B/C to match current DMV banding:
--   A — inner Montgomery (Bethesda/Chevy Chase/Potomac/Rockville/Silver Spring/
--       Takoma Park) and DC NW (Georgetown, Chevy Chase DC, AU Park, Dupont/West End)
--   B — rest of Montgomery, Prince George's, Howard, remainder of DC
--   C — rest of Maryland (Baltimore, Anne Arundel, Frederick, Eastern Shore, etc.)

INSERT INTO public.service_coverage_zones (
  zip_code, city, state, county, tier, tier_label, is_active, pricing_multiplier
)
