SELECT z.zip, pz.id
FROM (VALUES ('20007'), ('20008'), ('20015'), ('20016'), ('20036'), ('20037'), ('20810'), ('20811'), ('20812'), ('20813'), ('20814'), ('20815'), ('20816'), ('20817'), ('20818'), ('20824'), ('20825'), ('20827'), ('20847'), ('20848'), ('20849'), ('20850'), ('20851'), ('20852'), ('20853'), ('20854'), ('20857'), ('20859'), ('20889'), ('20891'), ('20892'), ('20894'), ('20895'), ('20896'), ('20901'), ('20902'), ('20903'), ('20904'), ('20905'), ('20906'), ('20907'), ('20908'), ('20910'), ('20911'), ('20912'), ('20914'), ('20915'), ('20916'), ('20918'), ('20993'), ('20997')) AS z(zip)
